ALTER TABLE events ENABLE ROW LEVEL SECURITY;
ALTER TABLE events FORCE ROW LEVEL SECURITY;

-- The application role can only ever see rows belonging to the org id
-- stamped on the current transaction. No org id set = no rows.
CREATE POLICY tenant_isolation ON events
  USING (org_id = current_setting('app.current_org', true)::uuid);

-- And it must not be able to write rows into someone else's tenant.
CREATE POLICY tenant_insert ON events
  FOR INSERT
  WITH CHECK (org_id = current_setting('app.current_org', true)::uuid);

// Constant memory: the cursor yields a batch, the transform formats it,
// the response consumes it. Nothing accumulates.
export async function streamExport(reply: FastifyReply, query: ExportQuery) {
  reply.raw.writeHead(200, {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': `attachment; filename="${query.filename}.csv"`,
  });

  reply.raw.write(toCsvRow(query.columns));

  for await (const batch of cursor(query, { batchSize: 5_000 })) {
    const chunk = batch.map(toCsvRow).join('');

    // Respect backpressure — a slow client must not inflate the heap.
    if (!reply.raw.write(chunk)) {
      await once(reply.raw, 'drain');
    }
  }

  reply.raw.end();
}
